import { ENV_VARS } from '@app/environment/environment.config';

/**
 * Push delivery is switched on BY PRESENCE of its secrets, like Resend, Stripe
 * and Cloudinary: without them a subscription is stored and the send is a quiet
 * no-op with one warning per process (push-dispatch.service.ts). The owner adds
 * the Firebase service account later; web push keys are generated by the agent.
 */
export type WebPushVapidConfig = {
  publicKey: string;
  privateKey: string;
  /** `mailto:` or https URL the push service may contact about abuse. */
  subject: string;
};

export const getWebPushConfig = (): WebPushVapidConfig | null => {
  const publicKey = ENV_VARS.WEB_PUSH_VAPID_PUBLIC_KEY;
  const privateKey = ENV_VARS.WEB_PUSH_VAPID_PRIVATE_KEY;
  const subject = ENV_VARS.WEB_PUSH_SUBJECT;
  if (!publicKey || !privateKey || !subject) {
    return null;
  }
  return { publicKey, privateKey, subject };
};

export type FirebaseServiceAccount = {
  project_id: string;
  client_email: string;
  private_key: string;
  token_uri: string;
};

/**
 * The service account arrives as ONE env value: raw JSON or base64 of it (the
 * env line is easier to paste as base64; Render accepts both). Missing or
 * malformed = FCM off.
 */
export const getFirebaseServiceAccount = (): FirebaseServiceAccount | null => {
  const raw = ENV_VARS.FIREBASE_SERVICE_ACCOUNT_JSON;
  if (!raw) {
    return null;
  }
  const candidates = [raw, safeBase64Decode(raw)];
  for (const candidate of candidates) {
    if (candidate === null) {
      continue;
    }
    try {
      const parsed: unknown = JSON.parse(candidate);
      if (isServiceAccount(parsed)) {
        return parsed;
      }
    } catch {
      // try the next shape
    }
  }
  return null;
};

const safeBase64Decode = (value: string): string | null => {
  try {
    return Buffer.from(value, 'base64').toString('utf8');
  } catch {
    return null;
  }
};

const isServiceAccount = (value: unknown): value is FirebaseServiceAccount =>
  typeof value === 'object' &&
  value !== null &&
  typeof (value as FirebaseServiceAccount).project_id === 'string' &&
  typeof (value as FirebaseServiceAccount).client_email === 'string' &&
  typeof (value as FirebaseServiceAccount).private_key === 'string' &&
  typeof (value as FirebaseServiceAccount).token_uri === 'string';
